INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(88332693, 'Assault Mode Zero', '爆裂模式・零', 'バスター・モード・ゼロ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只同调怪兽解放才能发动。包含那只怪兽卡名的1只「/爆裂体」怪兽当作「爆裂模式」的特殊召唤从手卡特殊召唤。 ②：自己主要阶段把墓地的这张卡除外才能发动。从手卡·卡组选1张「爆裂模式」在自己的魔法与陷阱区域盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(62633180, 'Assault on GHQ', '本阵强袭', '本陣強襲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上存在的1只怪兽发动。选择的卡破坏，之后，对方卡组最上面的2张卡送去墓地。'),
(93469007, 'Assault Overload', '爆裂爆发', 'バスター・バースト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上存在的1只名字带有「/爆裂体」的怪兽解放发动。双方受到那只怪兽的等级×200的数值的伤害。'),
(74431740, 'Assault Reboot', '爆裂重启', 'バスター・リブート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只「/爆裂体」怪兽解放才能发动。和那只怪兽卡名不同的1只「/爆裂体」怪兽无视召唤条件从卡组守备表示特殊召唤。 ②：把墓地的这张卡除外，以「爆裂再起」以外的自己墓地的有「爆裂模式」的卡名记述的卡以及「爆裂模式」任意数量为对象才能发动（同名卡最多1张）。那些卡回到卡组。'),
(56252810, 'Assault Revival', '再爆裂', 'Re－BUSTER', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己墓地存在的1张「爆裂模式」从游戏中除外发动。自己场上存在的怪兽全部破坏，自己墓地存在的1只名字带有「/爆裂体」的怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽的效果无效化，也不能解放，从场上离开的场合从游戏中除外。'),
(39015, 'Assault Sentinel', '爆裂狙击手', 'バスター・スナイパー', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从手卡·卡组把「爆裂狙击手」以外的1只有「爆裂模式」的卡名记述的怪兽特殊召唤。这个效果发动过的回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：以自己场上1只表侧表示怪兽为对象才能发动。把额外卡组1只同调怪兽给对方观看，作为对象的怪兽的种族·属性直到回合结束时变成和给人观看的怪兽相同。'),
(40012727, 'Assault Slash', '爆裂横扫', 'バスター・スラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「/爆裂体」的怪兽表侧表示存在的场合才能发动。场上表侧表示存在的怪兽全部破坏。'),
(18711696, 'Assault Sonic Warrior', NULL, NULL, 'Effect Monster', 'Warrior', 'WIND', 2, 1000, NULL, NULL),
(87043568, 'Assault Spirits', '强袭之魂', 'アサルト・スピリッツ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，给自己场上存在的1只怪兽装备。装备怪兽攻击的场合，那次伤害步骤时可以从手卡把1只攻击力1000以下的怪兽送去墓地，装备怪兽的攻击力直到结束阶段时上升送去墓地的怪兽的攻击力数值。这个效果1回合只能使用1次。'),
(77202120, 'Assault Synchron', '强袭同步士', 'アサルト・シンクロン', 'Tuner Monster', 'Machine', 'DARK', 2, 700, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡特殊召唤。那之后，自己受到700伤害。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：自己场上的表侧表示的龙族同调怪兽被解放的场合或者被除外的场合，把墓地的这张卡除外，以那1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(29863101, 'Assault Teleport', '爆裂瞬移', 'バスター・テレポート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己手卡让1只名字带有「/爆裂体」的怪兽回到卡组发动。从自己卡组抽2张卡。'),
(29311166, 'Assault Wyvern', '强袭翼龙', 'アサルトワイバーン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1800, 1100, '①：这张卡战斗破坏对方怪兽时，把这张卡解放才能发动。从自己的手卡·墓地选「强袭翼龙」以外的1只龙族怪兽特殊召唤。'),
(98520301, 'Asset Mountis', '资产炫耀螳螂', 'アセット・マウンティス', 'Effect Monster', 'Insect', 'LIGHT', 7, 2300, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：对方场上有6星以下的怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己手卡比对方多的场合才能发动。场上的全部怪兽的表示形式变更。场上的其他的昆虫族怪兽的属性·等级变成和这张卡相同。这个回合，自己不是昆虫族怪兽不能特殊召唤。 ③：这张卡被破坏的场合才能发动。从卡组把1只8星以上的昆虫族怪兽加入手卡。'),
(86762958, 'Assist★Yummy!', '协助★黯蜜！', 'アシスト★ヤミー！', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：自己·对方的准备阶段才能发动1次。自己回复100基本分，对方支付100基本分。 ②：自己·对方的主要阶段以及对方战斗阶段，把包含这张卡的自己场上2张表侧表示的「味美喵」卡送去墓地才能发动。自己或对方的场上·墓地1张卡回到手卡。 ③：把墓地的这张卡除外才能发动。从卡组把「协助摆位★味美喵！」以外的1张「味美喵」卡送去墓地。'),
(25592142, 'Astellar of the White Forest', '白森的阿斯特娅', '白き森のアステーリャ', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。从卡组把1只魔法师族·光属性调整特殊召唤。 ②：这张卡在墓地存在的状态，魔法·陷阱卡为让怪兽的效果发动而被送去自己墓地的场合才能发动。这张卡特殊召唤。'),
(69170403, 'Astra Ghouls', '距骨骰子食尸鬼团', 'アストラグールズ', 'Effect Monster', 'Zombie', 'EARTH', 5, NULL, 2000, '①：这张卡召唤成功时，以自己墓地1只4星以下的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段除外。 ②：1回合1次，自己主要阶段才能发动。掷1次骰子。自己场上的全部表侧表示怪兽的等级直到回合结束时变成和出现的数目相同。'),
(37053871, 'Astral Barrier', '星光体障壁', 'アストラルバリア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方怪兽攻击自己场上怪兽的场合，可以把那个攻击变成对自己基本分的直接攻击。'),
(64591429, 'Astral Kuriboh', '阿斯特拉尔・库里波', 'アストラル・クリボー', 'Effect Monster', 'Fiend', 'LIGHT', 1, 100, 100, '这个卡名的①的效果1回合只能使用1次。 ①：把额外卡组1只「No.」超量怪兽给对方观看才能发动。这张卡从手卡特殊召唤。这张卡的等级变成和给人观看的怪兽的阶级数值相同。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是「No.」超量怪兽不能从额外卡组特殊召唤。 ②：场上的这张卡为素材作超量召唤的「No.」怪兽得到以下效果。 ●这张卡不会被战斗以及对方的效果破坏。'),
(69852487, 'Astraltopia', '希望皇阿斯特拉尔・霍普', '希望皇アストラル・ホープ', 'Effect Monster', 'Warrior', 'LIGHT', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有超量怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：从自己的手卡·场上把这张卡以外的1张卡送去墓地才能发动。从卡组把以下的卡之内任意1张加入手卡。 ●「超量」魔法·陷阱卡 ●「拟声」魔法·陷阱卡 ●「异热同心」魔法·陷阱卡 ●「编号系」魔法·陷阱卡'),
(76794549, 'Astrograph Sorcerer', '宙读阵魔术士', 'アストログラフ・マジシャン', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 7, 2500, 2000, '①：自己场上的卡被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。那之后，可以选这个回合被破坏的1只自己或对方的怪兽，那1只同名怪兽从卡组加入手卡。 ②：把自己的手卡·场上·墓地的「灵摆龙」「超量龙」「同调龙」「融合龙」怪兽各1只和场上的这张卡除外才能发动。把1只「霸王龙 扎克」当作融合召唤从额外卡组特殊召唤。'),
(2134346, 'Asura Priest', '阿修罗', '阿修羅', 'Spirit Monster', 'Fairy', 'LIGHT', 4, 1700, 1200, '这张卡不能特殊召唤。召唤·反转回合的结束阶段时回到主人的手卡。可以对对方场上的全部怪兽攻击1次。'),
(88236094, 'Aswan Apparition', '阿斯旺的亡灵', 'アスワンの亡霊', 'Effect Monster', 'Fiend', 'DARK', 3, 500, 500, '这张卡对对方造成战斗伤害时，可以将自己墓地里的1张陷阱卡弹回卡组最上面。'),
(66719533, 'Asymmetaphys', '非对称玄化', 'アシンメタファイズ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段才能发动。从手卡把1张「玄化」卡除外，自己从卡组抽1张。 ②：1回合1次，自己的「玄化」卡被除外的场合发动。那个回合的以下效果适用。 ●自己回合：「玄化」怪兽以外的场上的全部怪兽的攻击力·守备力下降500。 ●对方回合：「玄化」怪兽以外的场上的全部怪兽的表示形式变更。'),
(6112401, 'At One With the Sword', '身剑一体', '身剣一体', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽只有表侧表示的名字带有「X-剑士」的怪兽1只的场合才能发动。发动后这张卡变成攻击力上升800的装备卡，给那1只怪兽装备。装备怪兽战斗破坏对方怪兽的场合，从自己卡组抽1张卡。'),
(48964966, 'Athena', '雅典娜', 'アテナ', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2600, 800, '①：1回合1次，把「雅典娜」以外的自己场上1只表侧表示的天使族怪兽送去墓地，以「雅典娜」以外的自己墓地1只天使族怪兽为对象才能发动。那只天使族怪兽特殊召唤。 ②：这张卡已在怪兽区域存在的状态，这张卡以外的天使族怪兽召唤·反转召唤·特殊召唤的场合发动。给与对方600伤害。'),
(8078366, 'Atlantean Attack Squad', '海皇的突击兵', '海皇の突撃兵', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1400, NULL, '自己场上有这张卡以外的鱼族·海龙族·水族怪兽存在的场合，这张卡的攻击力上升800。'),
(74311226, 'Atlantean Dragoons', '海皇的龙骑队', '海皇の竜騎隊', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1800, NULL, '①：只要这张卡在怪兽区域存在，自己的3星以下的海龙族怪兽可以直接攻击。 ②：这张卡为让水属性怪兽的效果发动而被送去墓地的场合发动。从卡组把「海皇的龙骑队」以外的1只海龙族怪兽加入手卡。'),
(37104630, 'Atlantean Heavy Infantry', '海皇的重装兵', '海皇の重装兵', 'Effect Monster', 'Sea Serpent', 'WATER', 2, NULL, 1600, '①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只4星以下的海龙族怪兽召唤。 ②：这张卡为让水属性怪兽的效果发动而被送去墓地的场合，以对方场上1张表侧表示的卡为对象发动。那张对方的表侧表示的卡破坏。'),
(706925, 'Atlantean Marksman', '海皇的狙击兵', '海皇の狙撃兵', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1400, NULL, '这张卡给与对方基本分战斗伤害时，可以从卡组把「海皇的狙击兵」以外的1只4星以下的名字带有「海皇」的海龙族怪兽特殊召唤。此外，这张卡为让水属性怪兽的效果发动而被送去墓地时，选择对方场上盖放的1张卡破坏。'),
(26976414, 'Atlantean Pikeman', '海皇的长矛兵', '海皇の長槍兵', 'Normal Monster', 'Sea Serpent', 'WATER', 2, 1400, NULL, '服侍着据说为海底支配者的海皇的长枪兵。从深暗海底袭击过来的长枪的连续攻击为深海鱼类们所畏惧。'),
(87340664, 'Atomic Firefly', '原子萤火虫', '原子ホタル', 'Effect Monster', 'Insect', 'LIGHT', 1, 100, 200, '战斗破坏以表侧表示存在于场上的这张卡的玩家受到1000点伤害。'),
(92361635, 'Atomic Scrap Dragon', '核能废铁龙', 'アトミック・スクラップ・ドラゴン', 'Synchro Monster', 'Dragon', 'EARTH', 10, 3200, 2400, '名字带有「废铁」的调整＋调整以外的怪兽2只以上 1回合1次，选择自己场上存在的1张卡和对方墓地存在的最多3张卡才能发动。选择的自己的卡破坏，选择的对方的卡回到卡组。这张卡被对方破坏送去墓地时，选择同调怪兽以外的自己墓地存在的1只名字带有「废铁」的怪兽特殊召唤。'),
(79875526, 'Attachment Cybern', '附属电子翼', 'アタッチメント・サイバーン', 'Effect Monster', 'Dragon', 'LIGHT', 3, 1600, 800, '这个卡名的③的效果1回合只能使用1次。 ①：以自己场上1只龙族·机械族的「电子」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作装备卡使用给那只怪兽装备。 ②：有这张卡装备的怪兽的攻击力上升600。 ③：给怪兽装备的这张卡被送去墓地的场合，以这张卡以外的自己墓地1只龙族·机械族的「电子」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(63689843, 'Attack and Receive', '白兵战', '白兵戦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己受到伤害的时候才可以发动。对方的基本分受到700分的伤害。自己的墓地还有「白兵战」存在的场合，对方受到（这些卡的数量×300）的伤害。'),
(31175914, 'Attack Gainer', '攻击吸取者', 'アタック・ゲイナー', 'Tuner Monster', 'Warrior', 'EARTH', 1, NULL, NULL, '这张卡作为同调召唤的素材送去墓地的场合，对方场上表侧表示存在的1只怪兽的攻击力直到结束阶段时下降1000。'),
(3103067, 'Attack Guidance Armor', '攻击诱导铠甲', '攻撃誘導アーマー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己或者对方的怪兽的攻击宣言时，可以从以下效果选择1个发动。 ●那只攻击怪兽破坏。 ●以那只攻击怪兽以外的自己或者对方场上1只怪兽为对象才能发动。攻击对象转移为那只怪兽进行伤害计算。'),
(84389640, 'Attack of the Cornered Rat', '穷鼠的进击', '窮鼠の進撃', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上存在的3星以下的通常怪兽进行战斗的场合，那个伤害步骤时支付100的倍数的基本分才能发动。直到这个回合的结束阶段时，进行战斗的1只对方怪兽的攻击力下降支付的数值。'),
(68786330, 'Attack Pheromones', '攻击信息素', 'アタック・フェロモン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上存在的爬虫类族怪兽向守备表示怪兽攻击的场合，那只怪兽在伤害步骤结束时变成表侧攻击表示。'),
(91989718, 'Attack Reflector Unit', '攻击反射装置', 'アタック・リフレクター・ユニット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只「电子龙」作为祭品才能发动。从自己的手卡·卡组特殊召唤1只「电子障壁龙」。'),
(83715234, 'Attack the Moon!', '削月刀', 'ムーン・スクレイパー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上的岩石族怪兽的表示形式变更时，可以选择对方场上1张魔法·陷阱卡破坏。这个效果1回合只能使用1次。'),
(85352446, 'Attention!', '统制训练', '統制訓練', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上表侧表示存在的1只5星以下的怪兽发动。场上表侧表示存在的持有那以外的等级的怪兽全部破坏。'),
(46083380, 'Attraffic Control', '攻通规制', '攻通規制', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上有怪兽3只以上存在的场合，对方不能攻击宣言。'),
(59048135, 'Augmented Heraldry', '升华的徽章', '昇華する紋章', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，场上的念动力族超量怪兽不会成为魔法·陷阱卡的效果的对象。此外，1回合1次，自己的主要阶段时从手卡丢弃1只名字带有「纹章兽」的怪兽才能发动。从卡组把「升华的纹章」以外的1张名字带有「纹章」的魔法·陷阱卡加入手卡。这个效果发动的回合，自己不是念动力族超量怪兽以及名字带有「纹章兽」的怪兽不能召唤·特殊召唤。'),
(4709881, 'Auram the World Chalice Blademaster', '星杯剑士 阿乌拉姆', '星杯剣士アウラム', 'Link Monster', 'Cyberse', 'FIRE', NULL, 2000, NULL, '「星杯」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升自己墓地的「星遗物」怪兽种类×300。 ②：把这张卡所连接区1只自己的「星杯」怪兽解放，以那只怪兽以外的自己墓地1只怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。 ③：这张卡从场上送去墓地的场合才能发动。从手卡把1只「星杯」怪兽特殊召唤。'),
(7183277, 'Aurkus, Lightsworn Druid', '光道德鲁伊 奥库斯', 'ライトロード・ドルイド オルクス', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 3, 1200, 1800, '只要这张卡在场上表侧表示存在，双方玩家不能把名字带有「光道」的怪兽作为魔法·陷阱·效果怪兽的效果的对象。此外，每次自己的结束阶段发动。从自己卡组上面把2张卡送去墓地。'),
(22386234, 'Aurora Paragon', '极光仙·阿诣罗', 'オーロラ・アンギラス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, 1000, '①：只要这张卡在怪兽区域存在，双方不能把怪兽特殊召唤。 ②：这张卡以外的怪兽召唤的场合发动。这张卡破坏。'),
(70089580, 'Aurora Wing', '极光翼鸟', 'オーロラ・ウィング', 'Effect Monster', 'Winged Beast', 'WATER', 4, 1200, 1600, '这张卡被战斗破坏送去墓地时，这张卡可以表侧攻击表示特殊召唤。「极光翼鸟」的效果1回合只能使用1次。'),
(62803464, 'Aussa the Earth Channeler', '地灵媒师 奥丝', '地霊媒師アウス', 'Effect Monster', 'Spellcaster', 'EARTH', 5, 1850, 1500, '这个卡名在规则上也当作「灵使」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只地属性怪兽丢弃才能发动。原本种族和丢弃的怪兽的其中任意种相同而攻击力是1850以下的1只地属性怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不能把地属性以外的怪兽的效果发动。 ②：自己的地属性怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。'),
(37970940, 'Aussa the Earth Charmer', '地灵使 奥丝', '地霊使いアウス', 'Flip Effect Monster', 'Spellcaster', 'EARTH', 3, 500, 1500, '①：这张卡反转的场合，以对方场上1只地属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到作为对象的怪兽的控制权。'),
(97661969, 'Aussa the Earth Charmer, Immovable', '崔嵬之地灵使 奥丝', '崔嵬の地霊使いアウス', 'Link Monster', 'Spellcaster', 'EARTH', NULL, 1850, NULL, '包含地属性怪兽的怪兽2只 这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以对方墓地1只地属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的地属性怪兽加入手卡。'),
(58990631, 'Automatic Laser', '自动式镭射炮', 'オートマチック・レーザー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方对攻击力1000以上的怪兽的召唤·特殊召唤成功时，把手卡1张「核成兽的钢核」给对方观看发动。那些怪兽破坏。'),
(71453557, 'Autonomous Action Unit', '自律行动装置', '自律行動ユニット', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：支付1500基本分，以对方墓地1只怪兽为对象才能把这张卡发动。那只怪兽在自己场上攻击表示特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。'),
(80250185, 'Autorokket Dragon', '自动枪弹龙', 'オートヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 3, 1600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，选场上1张魔法·陷阱卡送去墓地。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「自动手枪弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(29139104, 'Avalanching Aussa', '荒狂之奥丝', '荒ぶるアウス', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 800, 1500, '可以把自己场上除这张卡以外的1只地属性怪兽做祭品，从手卡特殊召唤1只地属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「荒狂之奥丝」从自己场上离开的场合破坏。'),
(82140600, 'Avalon', '约定之地 -阿瓦隆-', '約束の地 －アヴァロン－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以包含「阿托利斯」怪兽以及「兰斯洛特」怪兽各1只的自己墓地5只「圣骑士」怪兽为对象才能发动。那些怪兽除外，场上的卡全部破坏。'),
(51618973, 'Avance, Swordsman of the Nekroz', '影灵衣的魔剑士 阿凡斯', '影霊衣の魔剣士 アバンス', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1500, 800, '这个卡名的③的效果在决斗中只能使用1次。 ①：这张卡召唤时才能发动。从卡组把「影灵衣魔剑士 阿旺斯」以外的1只「影灵衣」怪兽特殊召唤。 ②：「影灵衣」仪式怪兽1只仪式召唤的场合，可以由自己场上的这1张卡作为仪式召唤需要的数值的解放使用。 ③：这张卡被效果解放的场合才能发动。自己的除外状态的「影灵衣」卡任意数量加入手卡（同名卡最多1张）。'),
(99284890, 'Avatar of The Pot', '壶魔神', '壺魔神', 'Effect Monster', 'Rock', 'EARTH', 3, 1200, 1300, '将1张「强欲之壶」从手卡送去墓地。从自己的卡组抽3张卡。'),
(91420202, 'Avendread Savior', '降诞疾仇尸者・救世主', 'アドヴェンデット・セイヴァー', 'Link Monster', 'Zombie', 'DARK', NULL, 1600, NULL, '不死族怪兽2只 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡只要在怪兽区域存在，卡名当作「归魂复仇死者·屠魔侠」使用。 ②：以自己墓地1张「复仇死者」卡为对象才能发动。那张卡加入手卡。 ③：这张卡和对方怪兽进行战斗的伤害计算时，从卡组把1只不死族怪兽送去墓地才能发动。那只对方怪兽的攻击力直到回合结束时下降送去墓地的怪兽的等级×200。'),
(69514125, 'Avenging Knight Parshath', '神圣骑士 珀耳修斯', '神聖騎士パーシアス', 'Synchro Monster', 'Fairy', 'LIGHT', 8, 2600, 2100, '调整＋调整以外的光属性怪兽1只以上 ①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽的表示形式变更。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(17469113, 'Avida, Rebuilder of Worlds', '双星神 阿－维达', '双星神 a－vida', 'Effect Monster', 'Cyberse', 'LIGHT', 11, 3500, 3500, '这张卡不能通常召唤。双方的场上·墓地有连接怪兽8种类以上存在的场合才能特殊召唤。把这张卡特殊召唤的回合，自己不能把其他怪兽特殊召唤。 ①：这张卡的特殊召唤不会被无效化。 ②：这张卡特殊召唤成功的场合发动。这张卡以外的双方的场上·墓地的怪兽以及除外中的怪兽全部回到持有者卡组。不能对应这个效果的发动让魔法·陷阱·怪兽的效果发动。'),
(82832464, 'Awakening of Nephthys', '奈芙蒂斯的觉醒', 'ネフティスの覚醒', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己场上的「奈芙提斯」怪兽的攻击力上升300。 ②：魔法与陷阱区域的表侧表示的这张卡被效果破坏送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「奈芙提斯」怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(12877076, 'Awakening of the Crystal Ultimates', '宝玉神觉醒', '宝玉神覚醒', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以把手卡1只「究极宝玉神」怪兽给对方观看，从以下效果选择1个发动。或者在自己场上有「究极宝玉神」怪兽存在的场合，可以从以下效果选择1个或者两方发动。 ●从卡组选1张「桥梁」卡或者「飞越虹桥」加入手卡或送去墓地。 ●选自己的手卡·卡组·墓地1只「宝玉兽」怪兽或者自己的魔法与陷阱区域1张「宝玉兽」怪兽卡特殊召唤。'),
(62256492, 'Awakening of the Possessed', '凭依觉醒', '憑依覚醒', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的怪兽的攻击力上升自己场上的怪兽的属性种类×300。 ②：自己场上的「灵使」怪兽以及「凭依装着」怪兽不会被效果破坏。 ③：自己场上有原本攻击力是1850的魔法师族怪兽召唤·特殊召唤的场合发动。自己抽1张。'),
(74426895, 'Awakening of the Possessed - Gagigobyte', '凭依觉醒－咖吉哥百特', '憑依覚醒－ガギゴバイト', 'Effect Monster', 'Reptile', 'WATER', 5, 2000, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以把自己场上的表侧表示的1只魔法师族怪兽和1只4星以下的水属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤时才能发动。对方手卡随机1张送去墓地。那之后，双方各自抽1张。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1张「水灵术」卡或「凭依」魔法·陷阱卡加入手卡。'),
(92652813, 'Awakening of the Possessed - Greater Inari Fire', '凭依觉醒－大稻荷火', '憑依覚醒－大稲荷火', 'Effect Monster', 'Pyro', 'FIRE', 5, 2000, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以把自己场上的表侧表示的1只魔法师族怪兽和1只4星以下的炎属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤时才能发动。给与对方为对方场上1只怪兽的原本攻击力数值的伤害。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1张「火灵术」卡或「凭依」魔法·陷阱卡加入手卡。'),
(65268179, 'Awakening of the Possessed - Nefariouser Archfiend', '凭依觉醒－恶魔收割者', '憑依覚醒－デーモン・リーパー', 'Effect Monster', 'Beast', 'EARTH', 5, 2000, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以把自己场上的表侧表示的1只魔法师族怪兽和1只4星以下的地属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤时才能发动。从自己墓地把1只4星以下的怪兽效果无效特殊召唤。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1张「地灵术」卡或「凭依」魔法·陷阱卡加入手卡。'),
(410904, 'Awakening of the Possessed - Rasenryu', '凭依觉醒－岚旋龙', '憑依覚醒－ラセンリュウ', 'Effect Monster', 'Dragon', 'WIND', 5, 2000, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以把自己场上的表侧表示的1只魔法师族怪兽和1只4星以下的风属性怪兽送去墓地，从手卡·卡组特殊召唤。 ②：这张卡的①的方法特殊召唤时才能发动。对方场上1张卡回到手卡。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1张「风灵术」卡或「凭依」魔法·陷阱卡加入手卡。'),
(53701259, 'Awakening of the Sacred Beasts', '觉醒的三幻魔', '覚醒の三幻魔', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：得到自己场上的「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」种类数量的以下效果。 ●1种类以上：每次对方对怪兽的召唤·特殊召唤成功，自己回复那些怪兽的攻击力数值的基本分。 ●2种类以上：对方场上的怪兽发动的效果无效化。 ●3种类：被送去对方墓地的怪兽不去墓地而除外。 ②：自己回合1次，自己场上有10星怪兽存在的场合才能发动。从自己墓地选1张永续陷阱卡加入手卡。'),
(30453613, 'Awakening of Veidos', '维都苏的觉醒', 'ヴェイドスの目覚め', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张「灰灭之都 奥布西地暮」在自己或对方的场地区域表侧表示放置。那之后，对方的场地区域有卡存在的场合，可以从卡组把1只5星以上的炎族·暗属性怪兽加入手卡。这张卡的发动后，直到回合结束时自己不是炎族怪兽不能从卡组·额外卡组特殊召唤。'),
(84914462, 'Axe Dragonute', '巨斧龙人', 'アックス・ドラゴニュート', 'Effect Monster', 'Dragon', 'DARK', 4, 2000, 1200, '①：这张卡攻击的场合，伤害步骤结束时变成守备表示。'),
(40619825, 'Axe of Despair', '恶魔之斧', 'デーモンの斧', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升1000。 ②：这张卡从场上送去墓地时，把自己场上1只怪兽解放才能发动。这张卡回到卡组最上面。'),
(19578592, 'Axe of Fools', '愚钝之斧', '愚鈍の斧', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升1000，效果无效化。 ②：自己准备阶段发动。给与装备怪兽的控制者500伤害。'),
(48305365, 'Axe Raider', '巨斧袭击者', 'アックス・レイダー', 'Normal Monster', 'Warrior', 'EARTH', 4, 1700, 1150, '持斧的战士。单手挥舞斧头的攻击相当强劲。'),
(33171768, 'Axon Kicker Oracle', '超能者神谕', 'サイキッカー・オラクル', 'Fusion Monster', 'Psychic', 'EARTH', 10, 2900, 1000, '念动力族怪兽＋同调·超量·连接怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡融合召唤时适用。这张卡的攻击力直到下个回合的结束时上升那些作为融合素材的同调·超量·连接怪兽数量×1000。 ②：对方把怪兽特殊召唤之际才能发动。那个无效，那些怪兽除外。 ③：融合召唤的这张卡被送去墓地的场合，从自己墓地把1张「瞬间移动」通常·速攻魔法卡除外才能发动。这张卡特殊召唤。'),
(42969214, 'Aye-Iron', '钢铁指猴', 'アイアイアン', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1800, '1回合1次，自己的主要阶段时可以让这张卡的攻击力上升400。这个效果发动的回合，这张卡不能攻击。'),
(42502956, 'Ayers Rock Sunrise', '艾尔斯岩日出', 'エアーズロック・サンライズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只兽族怪兽为对象才能发动。那只兽族怪兽特殊召唤，对方场上有表侧表示怪兽存在的场合，那些怪兽的攻击力直到回合结束时下降自己墓地的兽族·鸟兽族·植物族怪兽数量×200。'),
(17749468, 'Azamina', '圣徒人祖－赎罪神女', '贖罪神女', 'Fusion Monster', 'Illusion', 'LIGHT', 12, 4000, 4000, '「蓟花之妖魔」＋融合·同调怪兽 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把自己场上1只「圣蓟花」和对方场上1只表侧表示怪兽解放的场合可以从额外卡组特殊召唤。 ①：场上的这张卡不会被效果破坏。 ②：每次对方把魔法·陷阱·怪兽的效果发动，对方场上的全部怪兽的攻击力下降500。 ③：只要这张卡在怪兽区域存在，对方不能把攻击力0的怪兽的效果发动。'),
(39491690, 'Azamina Aphes', '圣徒・救赎', 'アザミナ・アーフェス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「白森林」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己的场上·墓地的恶魔族·幻想魔族·魔法师族的融合·同调怪兽数量的场上的卡为对象才能发动。那些卡回到手卡。 ②：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(20934683, 'Azamina Debtors', '圣徒・负疚', 'アザミナ・オフェイレーテス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己·对方的主要阶段才能发动。额外卡组1只「蓟花」融合怪兽给对方观看，那个等级每4星为1张的「罪宝」卡从自己的手卡·场上送去墓地（里侧表示卡翻开确认）。那之后，给人观看的怪兽当作融合召唤作特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「蓟花」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(42201897, 'Azamina Determination', '圣徒・棘路', 'アザミナ・ハマルティア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把额外卡组1只「蓟花」融合怪兽给对方观看，那个等级每4星为1张的自己的墓地·除外状态的「罪宝」卡回到卡组。那之后，给人观看的怪兽当作融合召唤作特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1张「罪宝」魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡在这个回合不能发动。'),
(46396218, 'Azamina Ilia Silvia', '背信圣徒 雷亚西尔薇亚', '背信聖徒シルヴィア', 'Fusion Monster', 'Illusion', 'DARK', 6, 1900, 1500, '幻想魔族怪兽＋魔法师族·光属性怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：「背信圣徒 森厄狼母」以外的自己的「蓟花」怪兽给与对方的战斗伤害变成2倍。 ②：对方把魔法·陷阱·怪兽的效果发动时，把这张卡解放才能发动。那个效果无效。 ③：这张卡被战斗·效果破坏的场合才能发动。从卡组把1张「罪宝」陷阱卡加入手卡。'),
(46174776, 'Azamina Moa Regina', '杀戮圣徒 摩尔蕾吉娜', '殺戮聖徒レジーナ', 'Fusion Monster', 'Illusion', 'DARK', 8, 3000, 2000, '幻想魔族怪兽＋6星以上的恶魔族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：以「杀戮圣徒 梦王鸦女」以外的自己墓地1只幻想魔族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：「杀戮圣徒 梦王鸦女」以外的「蓟花」卡或「罪宝」卡的效果发动时，以场上最多2张卡为对象才能发动。那些卡破坏。'),
(73391962, 'Azamina Mu Rcielago', '告死圣徒 姆露西耶拉格', '告死聖徒ルシエラーゴ', 'Fusion Monster', 'Illusion', 'DARK', 6, 2000, 2400, '幻想魔族怪兽＋魔法师族·光属性怪兽 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从卡组把1张「蓟花」卡或「罪宝」卡加入手卡。 ②：对方场上的怪兽的攻击力·守备力下降自己场上的「蓟花」怪兽数量×500。 ③：这张卡被战斗·效果破坏的场合才能发动。从卡组把1张「罪宝」魔法卡加入手卡。'),
(9785661, 'Azamina Sol Erysichthon', '饥渴圣徒 索尔厄律西克同', '飢渇聖徒エリュシクトーン', 'Fusion Monster', 'Illusion', 'DARK', 6, 2700, NULL, '幻想魔族怪兽＋恶魔族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，以场上1张卡为对象才能发动。那张卡送去墓地。 ②：自己·对方的准备阶段，以自己墓地1张「蓟花」卡或「罪宝」卡为对象才能发动。那张卡加入手卡。'),
(75081613, 'Aztekipede, the Worm Warrior', '巨型异虫', 'ジャイアントワーム', 'Effect Monster', 'Insect', 'EARTH', 4, 1900, 400, '这张卡不能通常召唤。把自己墓地存在的1只昆虫族怪兽从游戏中除外的场合才能特殊召唤。这张卡给与对方基本分战斗伤害时，从对方卡组上面把1张卡送去墓地。'),
(40908371, 'Azure-Eyes Silver Dragon', '苍眼银龙', '蒼眼の銀龍', 'Synchro Monster', 'Dragon', 'LIGHT', 9, 2500, 3000, '调整＋调整以外的通常怪兽1只以上 ①：这张卡特殊召唤的场合发动。自己场上的全部龙族怪兽直到下个回合的结束时不会被效果破坏，双方直到下个回合的结束时不能把那些作为效果的对象。 ②：自己准备阶段，以自己墓地1只通常怪兽为对象才能发动。那只怪兽特殊召唤。'),
(77411244, 'B-Buster Drake', 'B－爆裂龙兽', 'B－バスター・ドレイク', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1500, 1800, '①：1回合1次，可以把1个以下效果发动。 ●以自己场上1只机械族·光属性怪兽为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。 ②：装备怪兽不受对方的魔法卡的效果影响。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1只同盟怪兽加入手卡。'),
(89832901, 'B. Dragon Jungle King', '密林的黑龙王', '密林の黒竜王', 'Normal Monster', 'Dragon', 'EARTH', 6, 2100, 1800, '栖息在密林深处的漆黑龙王。咯吱咯吱的只知道啃食树木。'),
(975299, 'B.E.F. Zelos', '巨大要塞 泽洛斯', '巨大要塞ゼロス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从卡组把1张「头目连战」加入手卡。 ②：自己场上的「巨大战舰」怪兽的攻击力·守备力上升500，不会被对方的效果破坏，对方不能把那些作为效果的对象。 ③：1回合1次，自己主要阶段才能发动。从手卡把1只「巨大战舰」怪兽特殊召唤。 ④：自己场上有「巨大战舰」怪兽召唤·特殊召唤的场合发动。给那些怪兽放置1个自身的效果使用的指示物。'),
(14148099, 'B.E.S. Big Core', '巨大战舰 巨核', '巨大戦艦 ビッグ・コア', 'Effect Monster', 'Machine', 'DARK', 6, 2300, 1100, '这张卡召唤时放置3个指示物。这张卡不会被战斗破坏。进行战斗的场合，伤害步骤终了时取除这张卡的1个指示物。没有指示物的状态下进行战斗的场合，伤害步骤终了时这张卡破坏。'),
(75937826, 'B.E.S. Big Core MK-2', '巨大战舰 巨核Mk－Ⅱ', '巨大戦艦 ビッグ・コアMk－Ⅱ', 'Effect Monster', 'Machine', 'FIRE', 6, 2400, 1100, '这张卡特殊召唤成功时，给这张卡放置3个指示物。这张卡不会被战斗破坏。这张卡进行战斗的场合，伤害步骤结束时把这张卡放置的1个指示物取除。这张卡没有指示物的状态进行战斗的场合，伤害步骤结束时这张卡破坏。自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。'),
(82821760, 'B.E.S. Big Core MK-3', '巨大战舰 巨核Mk－Ⅲ', '巨大戦艦 ビッグ・コアMk－Ⅲ', 'Effect Monster', 'Machine', 'LIGHT', 8, 2700, 1900, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：这张卡召唤·特殊召唤的场合发动。给这张卡放置3个指示物。 ③：这张卡不会被战斗破坏。 ④：这张卡进行战斗的伤害步骤结束时发动。这张卡1个指示物取除。不能取除的场合，这张卡破坏。 ⑤：把墓地的这张卡除外才能发动。自己墓地的「巨大战舰」怪兽全部回到卡组。'),
(84257883, 'B.E.S. Blaster Cannon Core', '巨大战舰 爆裂大炮核', '巨大戦艦 ブラスターキャノン・コア', 'Effect Monster', 'Machine', 'EARTH', 9, 2500, 3000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合发动。给这张卡放置3个指示物。 ③：这张卡不会被战斗破坏。 ④：这张卡进行战斗的伤害步骤结束时发动。这张卡1个指示物取除。不能取除的场合，这张卡破坏。'),
(15317640, 'B.E.S. Covered Core', '巨大战舰 盖核', '巨大戦艦 カバード・コア', 'Effect Monster', 'Machine', 'EARTH', 7, 2500, 800, '这张卡召唤时放置2个指示物。这张卡不会被战斗破坏。进行战斗的场合，在伤害步骤结束时投掷硬币猜正反。猜错的场合，卡上的1个指示物取除。没有指示物放置的状态进行战斗的场合，伤害步骤结束时这张卡破坏。'),
(22790789, 'B.E.S. Crystal Core', '巨大战舰 晶核', '巨大戦艦 クリスタル・コア', 'Effect Monster', 'Machine', 'WATER', 5, 2100, 1000, '①：这张卡召唤的场合发动。给这张卡放置3个指示物。 ②：这张卡不会被战斗破坏。 ③：1回合1次，以对方场上1只表侧攻击表示怪兽为对象才能发动。那只对方的表侧攻击表示怪兽变成表侧守备表示。 ④：这张卡进行战斗的伤害步骤结束时发动。这张卡1个指示物取除。不能取除的场合，这张卡破坏。'),
(5121528, 'B.E.S. Derringer Core', '巨大战舰 德林杰核', '巨大戦艦 デリンジャー・コア', 'Effect Monster', 'Machine', 'LIGHT', 10, 1900, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只其他的「巨大战舰」怪兽给对方观看才能发动。这张卡从手卡特殊召唤。那之后，给这张卡放置3个指示物。 ②：自己·对方的主要阶段，可以把这张卡1个指示物取除，从以下效果选择1个发动。 ●把1张「头目连战」或者有那个卡名记述的魔法·陷阱卡从卡组加入手卡。 ●从自己墓地把1只9星以下的「巨大战舰」怪兽特殊召唤。'),
(44954628, 'B.E.S. Tetran', '巨大战舰 泰特朗', '巨大戦艦 テトラン', 'Effect Monster', 'Machine', 'WIND', 6, 1800, 2300, '这张卡召唤时放置3个指示物。这张卡不会被战斗破坏。进行战斗的场合，在伤害步骤结束时取除1个指示物。没有指示物放置的状态进行战斗的场合，伤害步骤结束时这张卡破坏。此外，可以把这张卡的1个指示物取除，破坏场上1张魔法·陷阱卡。这个效果1个回合只能使用1次。'),
(67073561, 'Baba Barber', '斗篷理发魔女姑娘', 'ミス・ケープ・バーバ', 'Link Monster', 'Fiend', 'DARK', NULL, 200, NULL, '怪兽2只 这个卡名的效果1回合只能使用1次。 ①：自己·对方的战斗阶段开始时，以这张卡或者这张卡所连接区1只怪兽为对象才能发动。那只怪兽直到结束阶段除外。'),
(88819587, 'Baby Dragon', '宝贝龙', 'ベビードラゴン', 'Normal Monster', 'Dragon', 'WIND', 3, 1200, 700, '不可轻视的幼龙，说不定隐藏着什么力量。'),
(40380686, 'Baby Mudragon', '泥龙宝宝', 'ドロゴン・ベビー', 'Tuner Monster', 'Dragon', 'DARK', 1, NULL, 200, '①：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ②：这张卡作为同调素材送去墓地的场合，宣言1个种族或者属性，以自己场上1只同调怪兽为对象才能发动。那只怪兽直到回合结束时变成宣言的种族或者属性。'),
(92729410, 'Baby Raccoon Ponpoko', '子狸 嘭嘭', '子狸ぽんぽこ', 'Effect Monster', 'Beast', 'EARTH', 2, 800, NULL, '这张卡召唤成功时，可以从卡组把「子狸 嘭嘭」以外的1只兽族·2星怪兽里侧守备表示特殊召唤。这个效果发动的回合，自己不能把兽族以外的怪兽特殊召唤。'),
(28118128, 'Baby Raccoon Tantan', '子狸 当当', '子狸たんたん', 'Flip Effect Monster', 'Beast', 'EARTH', 2, NULL, 800, '反转：从卡组把「子狸 当当」以外的1只兽族·2星怪兽特殊召唤。'),
(60023855, 'Baby Spider', '小蜘蛛', 'ベビー・スパイダー', 'Effect Monster', 'Insect', 'DARK', 3, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只暗属性怪兽解放才能发动。自己场上的全部「小蜘蛛」的等级上升因为这个效果发动而解放的怪兽的等级数值。 ②：把基本分支付一半，把墓地的这张卡除外，把自己场上的暗属性超量怪兽1个超量素材取除，以自己墓地1只暗属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(12533811, 'Baby Tiragon', '宝贝虎龙', 'ベビー・トラゴン', 'XYZ Monster', 'Dragon', 'EARTH', 1, 900, 900, '1星怪兽×3 自己的主要阶段1把这张卡1个超量素材取除，选择自己场上表侧表示存在的1只1星的怪兽才能发动。选择的怪兽可以直接攻击对方玩家。'),
(36042004, 'Babycerasaurus', '小角龙', 'ベビケラサウルス', 'Effect Monster', 'Dinosaur', 'EARTH', 2, 500, 500, '①：这张卡被效果破坏送去墓地的场合发动。从卡组把1只4星以下的恐龙族怪兽特殊召唤。'),
(56208713, 'Bacha the Melodious Maestra', '幻奏音姬 壮阔巴赫', '幻奏の音姫スペクタキュラー・バッハ', 'Fusion Monster', 'Fairy', 'LIGHT', 7, 2500, 1800, '「幻奏」怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1只「幻奏」怪兽特殊召唤。 ②：只要融合召唤的这张卡在怪兽区域存在，自己的「幻奏」融合怪兽发动的效果不会被无效化。 ③：这张卡被送去墓地的场合，以「幻奏的音姬 壮丽之巴赫」以外的自己墓地1只「幻奏」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(83272895, 'Bachibachibachi', '劈啪劈啪蜜蜂', 'バチバチバチ', 'Effect Monster', 'Insect', 'LIGHT', 3, 800, 800, '①：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(47453433, 'Back to Square One', '振出', '振り出し', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡。场上1只怪兽回到持有者卡组最上面。'),
(59919307, 'Back to the Front', '战线复归', '戦線復帰', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(68833958, 'Back-Up Rider', '一骑加势', '一騎加勢', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1500。'),
(82705573, 'Backfire', '逆火', 'バックファイア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次自己场上的表侧表示的炎属性怪兽被破坏送去墓地发动。给与对方500伤害。'),
(84976088, 'Background Dragon', '后台龙', 'バックグランド・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 5, 1600, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己场上没有卡存在的场合才能发动。墓地的这张卡和手卡1只4星以下的龙族怪兽守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(71172240, 'Backlinker', '反向连接兽', 'バックリンカー', 'Effect Monster', 'Cyberse', 'DARK', 3, 1600, NULL, '①：额外怪兽区域只有对方怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放才能发动。额外怪兽区域的怪兽全部回到持有者卡组。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。'),
(32603633, 'Backs to the Wall', '究极·背水之阵', '究極・背水の陣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把基本分支付到变成100才能发动。自己墓地的名字带有「六武众」的怪兽尽可能特殊召唤。（同名卡最多1张。但是，场上存在的同名卡不能特殊召唤。）'),
(30118811, 'Backup @Ignister', '备援＠伊格尼斯者', 'バックアップ＠イグニスター', 'Tuner Monster', 'Cyberse', 'DARK', 3, 1200, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的电子界族怪兽在自己场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「备份员@火灵天星」以外的1只电子界族·暗属性怪兽加入手卡。那之后，选自己1张手卡丢弃。'),
(97947705, 'Backup Operator', '备援操作员', 'バックアップ・オペレーター', 'Effect Monster', 'Cyberse', 'LIGHT', 3, 1200, 800, '这个卡名的效果1回合只能使用1次。 ①：以自己的连接怪兽的所连接区1只表侧表示怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到持有者手卡。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(63528891, 'Backup Secretary', '备援秘书', 'バックアップ・セクレタリー', 'Effect Monster', 'Cyberse', 'LIGHT', 3, 1200, 800, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有电子界族怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(36280194, 'Backup Soldier', '补充要员', '補充要員', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己的墓地的怪兽卡5张以上存在时才能发动。最多选择3张自己的墓地效果怪兽以外的攻击力1500以下的怪兽卡加入手卡。'),
(28486799, 'Backup Squad', '补充部队', '補充部隊', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次对方怪兽的攻击或者对方的效果让自己受到1000以上的伤害发动。那次伤害每有1000，自己从卡组抽1张。'),
(97677329, 'Backup Supervisor', '备份监管员', 'バックアップ・スーパーバイザー', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1200, NULL, '怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡是已用「备份秘书」为素材作连接召唤的场合在这张卡所连接区的自己怪兽和对方怪兽进行战斗的伤害步骤结束时才能发动。从手卡把1只电子界族怪兽特殊召唤。 ②：这张卡被战斗或者对方的效果破坏的场合才能发动。从自己的手卡·卡组·墓地选1只「备份秘书」特殊召唤。'),
(89328238, 'Backup Team', '补强要员', '補強要員', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己从卡组抽出对方场上的卡的数量。那之后，选抽出数量的自己手卡用喜欢的顺序回到卡组下面。 ②：这张卡在墓地存在，对方场上的卡数量比自己场上的卡多的场合，结束阶段才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(95637655, 'Backup Warrior', '后援战士', 'バックアップ・ウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 5, 2100, NULL, '这张卡不能通常召唤。自己场上存在的怪兽只有守备表示怪兽2只的场合可以特殊召唤。把这张卡特殊召唤的回合，自己不能同调召唤。'),
(82593786, 'Bacon Saver', '骨猪一掷', 'タスケルトン', 'Effect Monster', 'Zombie', 'DARK', 2, 700, 600, '怪兽进行战斗的战斗步骤时，把墓地的这张卡从游戏中除外才能发动。那只怪兽的攻击无效。这个效果在对方回合也能发动。「骨猪一掷」的效果在决斗中只能使用1次。'),
(46253216, 'Bad Aim', '友方误射', 'フレンドリーファイア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方的魔法·陷阱·怪兽的效果发动时，以那张卡以外的场上1张卡为对象才能发动。作为对象的卡破坏。'),
(76004142, 'Bad Luck Blast', '不运的爆弹', '不運の爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「不运的爆弹」在1回合只能发动1张。 ①：以对方场上1只表侧表示怪兽为对象才能发动。自己受到那只表侧表示怪兽的攻击力一半数值的伤害。那之后，给与对方为和自己受到的伤害相同数值的伤害。 ②：场上的这张卡被对方破坏送去墓地的场合发动。给与对方1000伤害。'),
(40633297, 'Bad Reaction to Simochi', '药物的副作用', 'シモッチによる副作用', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的基本分的回复的效果变成给与对方基本分的伤害的效果。'),
(88890658, 'Baelgrill de Nouvelles', '烧烤之巴格力尔・饿魔新飨', 'バグリエル・ド・ヌーベルズ', 'Ritual Effect Monster', 'Warrior', 'DARK', 6, 2400, 1850, '「食谱」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。对方场上的全部表侧表示的卡的效果直到回合结束时无效。「新式魔厨」怪兽的效果特殊召唤的场合，再把对方场上的怪兽尽可能解放。 ②：自己·对方回合，以对方场上1只攻击表示怪兽为对象才能发动。那只怪兽解放，从手卡·卡组把1只「饥饿的汉堡」特殊召唤。'),
(53318263, 'Bahalutiya, the Grand Radiance', '光之天穿 巴哈鲁提亚', '光の天穿バハルティヤ', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2000, 2400, '这张卡可以把1只效果怪兽解放作上级召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡在手卡存在，对方主要阶段对方用抽卡以外的方法从卡组把卡加入手卡的场合才能发动。这张卡上级召唤。 ②：这张卡从手卡的召唤·特殊召唤成功的场合才能发动。对方把自身手卡数量的卡从卡组上面里侧表示除外。那之后，对方让手卡全部回到卡组，这个效果除外的卡加入手卡。'),
(440556, 'Bahamut Shark', '巴哈姆特鲨', 'バハムート・シャーク', 'XYZ Monster', 'Sea Serpent', 'WATER', 4, 2600, 2100, '水属性4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。从额外卡组把1只3阶以下的水属性超量怪兽特殊召唤。这个效果的发动后，直到回合结束时这张卡不能攻击。'),
(7165085, 'Bait Doll', '诱饵人偶', 'おとり人形', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择魔法与陷阱卡区域盖放的1张卡发动。选择的卡翻开确认，那张卡是陷阱卡的场合，强制发动。发动时机不正确的场合，那个效果无效并破坏。那张卡是陷阱卡以外的场合，回到原状。这张卡发动后，不送去墓地回到卡组。'),
(94670654, 'Baku the Beast Ninja', '兽之忍者-貘', '獣の忍者－獏', 'Effect Monster', 'Beast', 'WIND', 3, 1500, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：这张卡特殊召唤·反转的场合，从自己墓地以及自己的魔法与陷阱区域的表侧表示的卡之中以「兽之忍者-貘」以外的1张「忍者」卡或者「忍法」卡为对象才能发动。那张卡回到持有者手卡。'),
(52495649, 'Balameuniere de Nouvelles', '黄油香煎之巴拉尼尔・饿魔新飨', 'バラムニエル・ド・ヌーベルズ', 'Ritual Effect Monster', 'Beast-Warrior', 'DARK', 5, 2000, 1850, '「食谱」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。把1张「新式魔厨」卡或者「食谱」卡从卡组加入手卡。 ②：以对方场上1只攻击表示怪兽为对象才能发动。那只怪兽解放，从手卡·卡组把1只6星「新式魔厨」仪式怪兽特殊召唤。这张卡是已用「新式魔厨」怪兽的效果特殊召唤的场合，这个效果在对方回合也能发动。'),
(67443336, 'Balance of Judgment', '裁决的天秤', '裁きの天秤', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方场上的卡数量比自己的手卡·场上的卡合计数量多的场合才能发动。自己从卡组抽出那个相差的数量。'),
(8567955, 'Balancer Lord', '负载均衡王', 'バランサーロード', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1700, 1200, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，支付1000基本分才能发动。这个回合自己在通常召唤外加上只有1次，自己主要阶段可以把1只电子界族怪兽召唤。 ②：这张卡被除外的场合才能发动。从手卡把1只4星以下的怪兽特殊召唤。'),
(242146, 'Ballista of Rampart Smashing', '破坏城壁的大枪', '城壁壊しの大槍', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽攻击里侧守备怪兽的场合，装备怪兽的攻击力上升1500。'),
(80584548, 'Ballista Squad', '弩弓部队', '弩弓部隊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只怪兽解放，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(39892082, 'Balloon Lizard', '气球蜥蜴', 'バルーン・リザード', 'Effect Monster', 'Reptile', 'EARTH', 4, 500, 1900, '每到自己的准备阶段时，在这张卡上放置1个指示物。破坏这张卡的卡的控制者受到这张卡上放置的指示物数量×400点的伤害。'),
(28062325, 'Bamboo Scrap', '竹头木屑', '竹頭木屑', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只植物族怪兽解放发动。在对方场上把2只「植物衍生物」（植物族·地·1星·攻800/守500）守备表示特殊召唤。'),
(300103003, 'Bandit', NULL, NULL, 'Skill Card', 'Keith', NULL, NULL, NULL, NULL, NULL),
(61528025, 'Banisher of the Light', '光之追放者', '光の追放者', 'Effect Monster', 'Fairy', 'LIGHT', 3, 100, 2000, '只要这张卡在场上表侧表示存在，被送去墓地的卡不去墓地从游戏中除外。'),
(94853057, 'Banisher of the Radiance', '闪光之追放者', '閃光の追放者', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1600, NULL, '只要这张卡在场上表侧表示存在，被送去墓地的卡不去墓地从游戏中除外。'),
(89569453, 'Banishing Trap Hole', '断绝落穴', '断絶の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把攻击力1500以下的怪兽召唤·反转召唤·特殊召唤时才能发动。那些攻击力1500以下的怪兽里侧除外。'),
(87112784, 'Banishment of the Darklords', '堕天使的放逐', '堕天使の追放', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把「堕天使的追放」以外的1张「堕天使」卡加入手卡。'),
(10012614, 'Banner of Courage', '勇气的旗印', '勇気の旗印', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的怪兽的攻击力在自己战斗阶段内上升200。'),
(48814566, 'Banquet of Millions', '魔兽之大饵', '魔獣の大餌', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的额外卡组的卡任意数量里侧表示除外，对方的额外卡组的里侧表示的卡随机选那个数量直到结束阶段表侧表示除外。'),
(55705473, 'Baobaboon', '狒狒面包树', 'バオバブーン', 'Effect Monster', 'Plant', 'DARK', 3, 1200, 1000, '①：这张卡召唤·特殊召唤成功的场合才能发动。自己从卡组抽1张，那之后选1张手卡回到卡组最上面或者最下面。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把「狒狒面包树」任意数量特殊召唤。'),
(81992475, 'Barbar, Malebranche of the Burning Abyss', '彼岸恶鬼 巴巴利却', '彼岸の悪鬼 バルバリッチャ', 'Effect Monster', 'Fiend', 'DARK', 3, 1700, 1000, '「彼岸的恶鬼 巴尔巴里恰」的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合，以「彼岸的恶鬼 巴尔巴里恰」以外的自己墓地最多3张「彼岸」卡为对象才能发动。那些卡除外，给与对方除外数量×300伤害。'),
(54702678, 'Barbaroid, the Ultimate Battle Machine', '极战机王 战神机人', '極戦機王ヴァルバロイド', 'Fusion Monster', 'Machine', 'EARTH', 12, 4000, 4000, '名字带有「机人」的机械族怪兽×5 这张卡在同1次的战斗阶段中可以作2次攻击。这张卡攻击的对方的效果怪兽的效果在伤害计算后无效化。这张卡战斗破坏对方怪兽的场合，给与对方基本分1000分伤害。这张卡不能向对方玩家直接攻击。'),
(30761649, 'Barian Untopia', '冀望乡－巴利安－', '冀望郷－バリアン－', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「异晶人的」卡使用。 ①：自己场上的「混沌超量」怪兽、「混沌No.」怪兽、「No.101」～「No.107」的「No.」怪兽不会成为对方的效果的对象，不会被对方的效果破坏。 ②：1回合1次，自己用「升阶魔法」魔法卡的效果对超量怪兽的特殊召唤成功的场合，以那1只超量怪兽和对方场上1只怪兽为对象才能发动。那只对方怪兽在那只超量怪兽下面重叠作为超量素材。'),
(97769122, 'Barian''s Chaos Draw', '巴利安之混沌抽牌', 'バリアンズ・カオス・ドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己抽卡阶段通过把通常抽卡的这张卡持续公开，那个回合的主要阶段1，可以从以下效果选择1个发动。 ●从卡组把1张「七皇」通常魔法卡送去墓地才能发动。这个效果变成和那张魔法卡发动时的效果相同。 ●从卡组把最多2只怪兽效果无效特殊召唤，用包含那些怪兽全部在内的自己场上的怪兽为素材把1只「No.」超量怪兽超量召唤。'),
(41925941, 'Bark of Dark Ruler', '冥王的咆哮', '冥王の咆哮', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的恶魔族怪兽进行战斗的场合，那个伤害步骤时支付100的倍数的基本分发动。直到这个回合的结束阶段时，进行战斗的1只对方怪兽的攻击力·守备力下降支付的数值。'),
(11813722, 'Barkion''s Bark', '木鳞龙的鳞片', 'パルキオンのうろこ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「自然」的怪兽表侧表示存在的场合才能发动。这个回合，对方不能把陷阱卡发动。'),
(62967433, 'Baromet the Sacred Sheep Shrub', '神羊树 巴罗梅特', '神羊樹バロメット', 'XYZ Monster', 'Plant', 'EARTH', 4, 1900, 2000, '4星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以自己墓地1张通常陷阱卡为对象才能发动。那张卡回到卡组最下面。那之后，自己抽1张。 ②：通常陷阱卡发动的场合才能发动。自己场上1个超量素材取除，从手卡把1只4星怪兽特殊召唤。'),
(86325596, 'Baron of the Fiend Sword', '邪剑男爵', '邪剣男爵', 'Normal Monster', 'Fiend', 'DARK', 4, 1550, 800, '操纵着充满怨念之剑的贵族，对追逐猎物的信念十分的执着。'),
(84815190, 'Baronne de Fleur', '鲜花之女男爵', 'フルール・ド・バロネス', 'Synchro Monster', 'Warrior', 'WIND', 10, 3000, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，以场上1张卡为对象才能发动。那张卡破坏。 ②：只在这张卡在场上表侧表示存在才有1次，魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。 ③：双方的准备阶段，以自己墓地1只9星以下的怪兽为对象才能发动。这张卡回到持有者的额外卡组，作为对象的怪兽特殊召唤。'),
(6840573, 'Barox', '巴洛克斯', 'バロックス', 'Fusion Monster', 'Fiend', 'DARK', 5, 1380, 1530, '「杀人熊猫」＋「石像怪」'),
(51369889, 'Barrage Blast', '扫射特攻', '掃射特攻', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，把自己场上的机械族超量怪兽的超量素材任意数量取除，以那个数量的场上的卡为对象才能发动。那些卡破坏。 ②：这张卡在墓地存在的状态，自己场上的机械族超量怪兽被战斗或者对方的效果破坏的场合，从自己墓地把这张卡和1只机械族超量怪兽除外才能发动。给与对方除外的怪兽的阶级×200伤害。'),
(78783370, 'Barrel Behind the Door', '地狱的冷枪', '地獄の扉越し銃', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '给与战斗伤害以外的伤害的效果发动时才能发动这张卡。将自己所受的伤害转给对方。'),
(81480461, 'Barrel Dragon', '左轮手枪龙', 'リボルバー・ドラゴン', 'Effect Monster', 'Machine', 'DARK', 7, 2600, 2200, NULL),
(67841515, 'Barrel Lily', '枪管百合', 'マグナム・リリィ', 'Normal Monster', 'Plant', 'EARTH', 3, 1100, 600, '所谓的铁炮百合。就是射出花粉攻击。'),
(10476868, 'Barrel Rock', '机枪岩', 'ガンロック', 'Normal Monster', 'Rock', 'EARTH', 4, 1000, 1300, '一边用双肩的机关枪发射，一边用身体乱撞进行攻击。'),
(13117073, 'Barricadeborg Blocker', '杜宾警卫拦路者', '警衛バリケイドベルグ', 'Link Monster', 'Machine', 'DARK', NULL, 1000, NULL, '卡名不同的怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合，丢弃1张手卡才能发动。这个回合的结束阶段，从自己墓地把1张永续魔法卡或场地魔法卡加入手卡。 ②：只要这张卡在怪兽区域存在，自己场上的表侧表示的魔法卡不会被对方的效果破坏。'),
(98477480, 'Barrier of the Voiceless Voice', '肃声结界', '粛声なる結界', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有「肃声的祈祷者 理」以及光属性仪式怪兽存在，对方怪兽只能选择仪式怪兽作为攻击对象，对方不能把自己场上的光属性怪兽作为效果的对象。 ②：自己主要阶段才能发动。除「肃声之结界」外的1张「肃声」卡或1只「法理守护者」仪式怪兽从卡组加入手卡。'),
(89127526, 'Barrier Resonator', '护罩共鸣者', 'バリア・リゾネーター', 'Tuner Monster', 'Fiend', 'LIGHT', 1, 300, 800, '把这张卡从手卡送去墓地，选择自己场上表侧表示存在的1只调整发动。选择的怪兽在这个回合不会被战斗破坏，选择的怪兽的战斗发生的对自己的战斗伤害变成0。这个效果在对方回合也能发动。'),
(84478195, 'Barrier Statue of the Abyss', '深渊之结界像', '深淵の結界像', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1000, '①：只要这张卡在怪兽区域存在，双方不是暗属性怪兽不能特殊召唤。'),
(19740112, 'Barrier Statue of the Drought', '干旱之结界像', '干ばつの結界像', 'Effect Monster', 'Rock', 'EARTH', 4, 1000, 1000, '①：只要这张卡在怪兽区域存在，双方不是地属性怪兽不能特殊召唤。'),
(46145256, 'Barrier Statue of the Heavens', '闪光之结界像', '閃光の結界像', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1000, 1000, '①：只要这张卡在怪兽区域存在，双方不是光属性怪兽不能特殊召唤。'),
(47961808, 'Barrier Statue of the Inferno', '业火之结界像', '業火の結界像', 'Effect Monster', 'Pyro', 'FIRE', 4, 1000, 1000, '①：只要这张卡在怪兽区域存在，双方不是炎属性怪兽不能特殊召唤。'),
(73356503, 'Barrier Statue of the Stormwinds', '烈风之结界像', '烈風の結界像', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1000, 1000, '①：只要这张卡在怪兽区域存在，双方不是风属性怪兽不能特殊召唤。'),
(10963799, 'Barrier Statue of the Torrent', '豪雨之结界像', '豪雨の結界像', 'Effect Monster', 'Aqua', 'WATER', 4, 1000, 1000, '只要这张卡在场上表侧表示存在，双方不能把水属性以外的怪兽特殊召唤。'),
(96700602, 'Barrier Wave', '波动障壁', '波動障壁', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时，把自己场上存在的1只同调怪兽解放发动。对方场上攻击表示存在的怪兽全部变成守备表示。那之后，给与对方基本分攻击宣言的怪兽的守备力数值的伤害。'),
(69167267, 'Basal Rose Shoot', '馨香蔷薇之发芽', '薫り貴き薔薇の芽吹き', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地选1只「蔷薇龙」怪兽守备表示特殊召唤。 ②：盖放的这张卡被破坏的场合，从自己墓地的怪兽以及除外的自己怪兽之中以1只「黑蔷薇龙」或者1只有那个卡名记述的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(88610708, 'Bashing Shield', '盾牌猛击', 'シールドバッシュ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '通常召唤的怪兽才能装备。 ①：装备怪兽的攻击力上升1000。 ②：装备怪兽的战斗发生的对自己的战斗伤害变成0。'),
(89091579, 'Basic Insect', '昆虫人', '昆虫人間', 'Normal Monster', 'Insect', 'EARTH', 2, 500, 700, '群居生活的昆虫。森林中是他们的乐园。'),
(81344637, 'Basilius, Familiar of the Evil Eye', '咒眼之眷属 巴西利乌斯', '呪眼の眷属 バジリウス', 'Effect Monster', 'Fiend', 'DARK', 3, 400, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「咒眼」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己主要阶段才能发动。从卡组把1张「咒眼」魔法·陷阱卡送去墓地。'),
(65351555, 'Basiltrice, Familiar of the Evil Eye', '咒眼之眷属 巴西利科克', '呪眼の眷属 バジリコック', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，这张卡在手卡·墓地存在，自己场上有「咒眼」怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：对方回合才能发动。用自己场上的怪兽为连接素材把1只「咒眼」连接怪兽连接召唤。那个时候，可以让自己场上的「咒眼」装备魔法卡作为「咒眼」怪兽来成为连接素材。'),
(72076281, 'Bat', '机械蝙蝠', 'バット', 'Normal Monster', 'Machine', 'WIND', 1, 300, 350, '投下左右翅膀里搭载的爆弹的机械蝙蝠。'),
(80447641, 'Bat, the Forest Ninja', '森之忍者 蝠宝', '森の忍者 バット', 'Tuner Monster', 'Beast', 'LIGHT', 3, 800, 800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场地区域有表侧表示卡存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，若自己的场上或墓地有「童话故事 序章 启程的曙光」存在则能发动。从卡组把1只兽族·光属性怪兽加入手卡。'),
(61181383, 'Battery Charger', '充电器', '充電器', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付500基本分。从自己墓地特殊召唤1只名字带有「电池人」的怪兽。'),
(60549248, 'Batteryman 9-Volt', '电池人－角型', '電池メン－角型', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1000, 1000, '「电池人-角型」的①的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功时才能发动。从卡组把1只「电池人」怪兽加入手卡，这张卡的攻击力·守备力变成原本的2倍。 ②：自己结束阶段发动。这张卡破坏。'),
(63142001, 'Batteryman AA', '电池人-单三型', '電池メン－単三型', 'Effect Monster', 'Thunder', 'LIGHT', 3, NULL, NULL, '●自己场上的「电池人-单三型」全部攻击表示的场合，每存在1张「电池人-单三型」这张卡的攻击力上升1000。 ●自己场上的「电池人-单三型」全部守备表示的场合，每存在1张「电池人-单三型」这张卡的守备力上升1000。'),
(47346845, 'Batteryman AAA', '电池人-单四型', '電池メン－単四型', 'Effect Monster', 'Thunder', 'LIGHT', 4, NULL, NULL, '这张卡召唤·反转时，可以把自己的手卡·墓地存在的1只「电池人-单四型」特殊召唤。'),
(19733961, 'Batteryman C', '电池人-单二型', '電池メン－単二型', 'Effect Monster', 'Thunder', 'LIGHT', 2, NULL, NULL, '●当自己场上的「电池人-单二型」全部攻击表示的场合：每有1只「电池人-单二型」，自己场上的全部机械族怪兽攻击力上升500。 ●当自己场上的「电池人-单二型」全部守备表示的场合：每有1只「电池人-单二型」，自己场上的全部机械族怪兽守备力上升500。'),
(83446909, 'Batteryman Charger', '充电池人', '充電池メン', 'Effect Monster', 'Thunder', 'LIGHT', 5, 1800, 1200, '这张卡的召唤成功时，可以从自己的手卡·卡组把1只「充电池人」以外的名字带有「电池人」的怪兽特殊召唤。这张卡的攻击力·守备力上升自己场上表侧表示存在的雷族怪兽数量×300的数值。'),
(55401221, 'Batteryman D', '电池人-单一型', '電池メン－単一型', 'Effect Monster', 'Thunder', 'LIGHT', 1, NULL, 1900, '只要这张卡在自己场上表侧表示存在，对方不能选择自己场上存在的「电池人-单一型」以外的雷族怪兽作为攻击对象。'),
(74730899, 'Batteryman Fuel Cell', '燃料电池人', '燃料電池メン', 'Effect Monster', 'Thunder', 'LIGHT', 6, 2100, NULL, '自己场上有名字带有「电池人」的怪兽表侧表示2只以上存在的场合，这张卡可以从手卡特殊召唤。1回合1次，可以把这张卡以外的自己场上存在的1只名字带有「电池人」的怪兽解放，选择对方场上存在的1张卡回到持有者手卡。'),
(19441018, 'Batteryman Industrial Strength', '电池人-业务用', '電池メン－業務用', 'Effect Monster', 'Thunder', 'LIGHT', 8, 2600, NULL, '这张卡不能通常召唤。把自己墓地2只名字带有「电池人」的怪兽从游戏中除外的场合才能特殊召唤。1回合1次，把自己墓地1只雷族怪兽从游戏中除外才能发动。选择场上1只怪兽和1张魔法·陷阱卡破坏。'),
(56839613, 'Batteryman Micro-Cell', '电池人-纽扣型', '電池メン－ボタン型', 'Flip Effect Monster', 'Thunder', 'LIGHT', 1, 100, 100, '反转：从自己卡组把1只「电池人-纽扣型」以外的4星以下的名字带有「电池人」的怪兽特殊召唤。此外，反转过的这张卡被战斗破坏送去墓地时，从自己卡组抽1张卡。'),
(44586426, 'Batteryman Solar', '太阳电池人', '太陽電池メン', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1500, 1500, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只雷族怪兽送去墓地。 ②：这张卡已在怪兽区域存在的状态，雷族怪兽召唤·特殊召唤的场合发动。在自己场上把1只「电池人衍生物」（雷族·光·1星·攻/守0）特殊召唤。 ③：以自己的场上·墓地1只「电池人」效果怪兽为对象才能发动。直到结束阶段，这张卡当作那同名卡使用。'),
(44586427, 'Batteryman Token', '太阳电池人', '太陽電池メン', 'Token', 'Thunder', NULL, NULL, NULL, NULL, NULL),
(22047978, 'Battle Break', '战斗中止', 'バトル・ブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。对方可以从手卡把1只怪兽给人观看让这张卡的效果无效。没给观看的场合，那只攻击怪兽破坏，战斗阶段结束。'),
(10389143, 'Battle Eagle Token', '编号42 星舰・银河战斧', 'No.42 スターシップ・ギャラクシー・トマホーク', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(19665973, 'Battle Fader', '消战者', 'バトルフェーダー', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤。那之后，战斗阶段结束。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(48094997, 'Battle Footballer', '战斗橄榄球员', 'バトルフットボーラー', 'Normal Monster', 'Machine', 'FIRE', 4, 1000, 2100, '以高守备能力自豪的电子人。据说原本是作为橄榄球机器开发的。'),
(43225434, 'Battle Fusion', '决斗融合', '決闘融合－バトル・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「决斗融合」在1回合只能发动1张。 ①：自己场上的融合怪兽和对方怪兽进行战斗的攻击宣言时才能发动。那只自己怪兽的攻击力直到伤害步骤结束时上升进行战斗的对方怪兽的攻击力数值。'),
(60534585, 'Battle Instinct', '斗争本能', '闘争本能', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方宣言直接攻击时，自己场上没有怪兽存在的场合才能发动。从手卡把1只4星以下的兽族怪兽表侧攻击表示特殊召唤。'),
(31245780, 'Battle Mania', '战斗狂', 'バトルマニア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回合的准备阶段时才能发动。对方场上表侧表示存在的怪兽全部变成攻击表示，这个回合表示形式不能改变。此外，这个回合可以攻击的对方怪兽必须作出攻击。'),
(46570372, 'Battle of Sleeping Spirits', '镇魂的决斗', '鎮魂の決闘', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：双方可以从自身墓地选这个回合被战斗破坏的1只怪兽攻击表示特殊召唤。这个效果让自己特殊召唤的怪兽是「元素英雄 新宇侠」的场合，这个回合，那只怪兽和对方怪兽进行战斗的伤害步骤内，那只怪兽的攻击力变成2倍。'),
(60530944, 'Battle of the Elements', '异种斗争', '異種闘争', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '双方场上存在的怪兽全部表侧表示的场合才能发动。双方玩家直到各自属性变成1种类，把场上的自己怪兽送去墓地。'),
(5053103, 'Battle Ox', '牛头人', 'ミノタウルス', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1700, 1000, '拥有惊人力量的牛形怪物。斧头一挥横扫一切。');